<script setup lang="ts">
import {computed,ref,onMounted,onBeforeUnmount} from 'vue';
import {usePlatform} from '../stores/platform';
import {request,isRequestCanceled} from '../api/client';
import {timeRange,codes} from '../api/gateway';
import type {components} from '../api/schema';
import type {Field,Capture} from '../domain';
import RemoteAssetImage from './RemoteAssetImage.vue';
import QueryForm from './QueryForm.vue';import DeviceMap from './DeviceMap.vue';import DataTable from './DataTable.vue';import ChartPanel from './ChartPanel.vue';
type S=components['schemas'];const p=usePlatform(),timeline=ref(0),error=ref(''),heat=ref(false);let controller=new AbortController();
const distribution=computed(()=>p.active==='设备分布');
const fields=computed<Field[]>(()=>distribution.value?[{key:'sites',label:'场所',options:p.db.sites.map(s=>({label:s.name,value:s.id})),multiple:true},{key:'devices',label:'设备',options:p.db.devices.map(d=>({label:d.name,value:d.id})),multiple:true},{key:'status',label:'在线状态',options:['全部','在线','离线']},{key:'keyword',label:'设备关键字'}]:[{key:'type',label:'数据类型',options:['电围','车牌','MAC','人像','综合']},{key:'site',label:'场所',options:['全部',...p.db.sites.map(s=>s.name)]},{key:'start',label:'采集开始',type:'datetime-local'},{key:'end',label:'采集结束',type:'datetime-local'},{key:'target',label:'IMSI / 车牌 / MAC / 人像'},...(!p.f.type||p.f.type==='电围')?[{key:'imei',label:'IMEI'}]:[]]);
const points=computed(()=>p.mapTrajectory?(p.remote.trajectory?.items||[]).slice(0,timeline.value||undefined):[]),selected=computed(()=>p.db.devices.filter(d=>p.mapSelected.includes(d.id)));
async function guarded(run:()=>Promise<void>){error.value='';try{await run();}catch(e){if(!isRequestCanceled(e))error.value=e instanceof Error?e.message:String(e);}}
async function loadHeat(enabled:boolean){heat.value=enabled;if(!enabled){controller.abort();return;}await guarded(async()=>{controller.abort();controller=new AbortController();const range=p.f.start&&p.f.end?timeRange(p.f):timeRange({start:new Date(Date.now()-86400000).toISOString(),end:new Date().toISOString()});const siteId=p.db.sites.find(s=>s.name===p.f.site)?.id;p.remote.heatmap=(await request('getMapHeatmap',{query:{bbox:'-180,-85,180,85',zoom:12,limit:500,from:range.from,to:range.to,siteId,dataType:codes[String(p.f.type) as keyof typeof codes],siteIds:Array.isArray(p.f.sites)?p.f.sites:undefined,deviceIds:Array.isArray(p.f.devices)?p.f.devices:undefined},signal:controller.signal})).data;});}
async function area(geometry:S['GeoPolygon']){await guarded(async()=>{if(controller.signal.aborted)controller=new AbortController();const type=String(p.f.type||'综合');const range=p.f.start&&p.f.end?timeRange(p.f):timeRange({start:new Date(Date.now()-86400000).toISOString(),end:new Date().toISOString()});p.remote.areaSummary=(await request('getMapAreaSummary',{body:{spatialRange:{selectionType:'AREA',coordinateSystem:'EPSG:4326',geometry},timeRange:range,dataTypes:type==='综合'?['FENCE','MAC','PLATE','FACE']:[codes[type as keyof typeof codes]||'FENCE']},signal:controller.signal})).data;});}
function reset(){p.mapSelected=[];p.mapTrajectory=false;timeline.value=0;p.remote.trajectory=null;p.remote.heatmap=null;p.remote.areaSummary=null;heat.value=false;p.reset();}
async function query(){timeline.value=0;await p.query();if(heat.value)await loadHeat(true);}
onMounted(()=>{if(distribution.value)void area({type:'Polygon',coordinates:[[[-180,-85],[180,-85],[180,85],[-180,85],[-180,-85]]]});});onBeforeUnmount(()=>controller.abort());
</script>
<template><QueryForm :fields="fields" :model="p.f" @search="query" @reset="reset"/><el-alert v-if="error" type="error" :title="error" :closable="false"/><div class="query-split"><div class="stack"><DeviceMap :devices="p.db.devices" :selected="p.mapSelected" :distribution="distribution" :points="points" :heat-cells="p.remote.heatmap?.cells" @select="p.mapSelected=$event" @reset="reset" @area="area" @heat="loadHeat"/><ChartPanel v-if="distribution&&p.remote.areaSummary" title="所选区域设备在线率" :rows="p.remote.areaSummary.regions.map(r=>({日期:r.regionCode,在线率:r.onlineRate*100}))" :labels="['在线率']" unit="%"/><DataTable v-if="!distribution" :rows="p.db.captures" :columns="[{key:'time',label:'采集时间'},{key:'type',label:'类型'},{key:'target',label:'目标标识'},{key:'site',label:'场所'},{key:'device',label:'设备',link:true}]" @select="p.chosen=$event" @open="row=>p.deviceInfo(String(row.deviceId))"><template #actions><el-button @click="p.mapTrajectory=!p.mapTrajectory;timeline=0">展示轨迹</el-button></template></DataTable><section v-if="p.mapTrajectory&&!distribution" class="card"><h3>轨迹时间轴</h3><el-slider v-model="timeline" :min="0" :max="p.remote.trajectory?.items.length||0"/><p>{{p.remote.trajectory?.items[Math.max(0,timeline-1)]?.captureTime}}</p><el-button @click="timeline=Math.min(p.remote.trajectory?.items.length||0,timeline+1)">下一点</el-button></section></div><aside class="stack"><section class="card"><h3>已选设备</h3><el-empty v-if="!selected.length" description="请框选或单选地图设备" :image-size="80"/><article v-for="d in selected" :key="d.id"><el-button link type="primary" @click="p.deviceInfo(d.id)">{{d.name}}</el-button><p>{{d.site}} · {{d.status}}</p></article><div class="actions"><el-button :disabled="!selected.length" @click="p.navigate('设备管理',{ids:selected.map(d=>d.id)})">设备详情</el-button><el-button v-if="!distribution" @click="p.formAnalysis('区域统计')">区域统计</el-button><el-button v-if="!distribution" :disabled="!p.chosen.length" @click="p.dataAction('伴随',p.chosen as unknown as Capture[])">伴随分析</el-button></div></section><section v-if="p.remote.areaSummary" class="card"><h3>框选区域摘要</h3><p>采集总量 {{p.remote.areaSummary.captureCount}}</p><p>场所 {{p.remote.areaSummary.siteCount}} · 设备 {{p.remote.areaSummary.deviceCount}}</p><p>在线率 {{(p.remote.areaSummary.onlineRate*100).toFixed(1)}}%</p><p class="muted">统计截至 {{p.remote.areaSummary.asOf}}</p></section><section v-if="p.remote.mapProfile?.profileType==='PERSON'" class="card person-info"><h3>目标基本信息</h3><RemoteAssetImage :asset-id="p.remote.mapProfile.person.portraitAssetId" :alt="p.remote.mapProfile.displayLabel"/><dl><dt>姓名</dt><dd>{{p.remote.mapProfile.person.nameMasked||p.remote.mapProfile.displayLabel}}</dd><dt>性别</dt><dd>{{p.remote.mapProfile.person.gender||'未知'}}</dd><dt>民族</dt><dd>{{p.remote.mapProfile.person.ethnicity||'未知'}}</dd><dt>手机号码</dt><dd>{{p.remote.mapProfile.person.phoneMasked||'未提供'}}</dd><dt>身份证号码</dt><dd>{{p.remote.mapProfile.person.identityNumberMasked||'未提供'}}</dd><dt>常驻地区</dt><dd>{{p.remote.mapProfile.person.residenceRegionCode||'未提供'}}</dd><dt>疑似落脚点</dt><dd>{{p.remote.mapProfile.person.suspectedLandingText||'未提供'}}</dd><dt>外貌特征</dt><dd>{{p.remote.mapProfile.person.appearanceDescription||'未提供'}}</dd><dt>被设备捕捉次数</dt><dd>{{p.remote.mapProfile.captureCount}}</dd><dt>经过站点次数</dt><dd>{{p.remote.mapProfile.siteCount}}</dd><dt>经过区域</dt><dd>{{p.remote.mapProfile.visitedRegionCodes.join('、')||'未提供'}}</dd></dl></section></aside></div></template>
